import csv,importlib.util,numpy as np,pymc as pm
def load(p,n):
    spec=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
rows=list(csv.DictReader(open('responses.csv')))
out={}
for name,p in [('inc','models/anchored_neighbourhood_side_channel.py'),('new','iter_1/candidate_3_repair_1/candidate.py')]:
    m=load(p,name); d=m.prepare_observed(rows)
    with m.model: pm.set_data(d)
    ip=m.model.initial_point()
    print(list(ip))
    for k in ip:
        if k.startswith('slip'): ip[k]=np.array(-30.)
    out[name]=m.model.compile_fn(m.model['p_yes'],inputs=m.model.value_vars,on_unused_input='ignore')(ip)
a,b=out['inc'],out['new']; i=np.argsort(-abs(a-b))[:5]; print(a[i],b[i],[rows[j]['number_set']+'|'+rows[j]['target'] for j in i])
EOF

